INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷81·晋少帝本纪·天福七年十一月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f7f6cfbef8465951e2f967177b4e0970e9d71ed0/content/books/zizhi-tongjian/vol-283/year-0942/part-05/sources/library/jiuwudaishi-081-942-salt/source.txt", "note": "《旧五代史》卷81·晋少帝本纪·天福七年十一月，段落 jiu-wudaishi-205deb4a7860-p001983；已核上下文及传主，纸本及异文待核。", "id": "339cc68d-7f97-514c-99fa-e779b48fe477"}, {"title": "新五代史·卷29·景延广传·晋与契丹交涉", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f7f6cfbef8465951e2f967177b4e0970e9d71ed0/content/books/zizhi-tongjian/vol-283/year-0942/part-05/sources/library/xinwudaishi-029-jing-khitan/source.txt", "note": "《新五代史》卷29·景延广传·晋与契丹交涉，段落 xin-wudaishi-b08f244b9241-p001067；已核上下文及传主，纸本及异文待核。", "id": "82078cac-bb42-5526-b3f6-656e97070284"}, {"title": "新五代史·卷72·四夷附录·出帝初立交涉", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f7f6cfbef8465951e2f967177b4e0970e9d71ed0/content/books/zizhi-tongjian/vol-283/year-0942/part-05/sources/library/xinwudaishi-072-jin-khitan/source.txt", "note": "《新五代史》卷72·四夷附录·出帝初立交涉，段落 xin-wudaishi-b08f244b9241-p003606；已核上下文及传主，纸本及异文待核。", "id": "17905f15-3966-5b4a-89b5-648243292f9e"}, {"title": "资治通鉴·卷283·天福七年八月至年末", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0f7599ab625e6aecad46626068a963056a59c78/content/books/zizhi-tongjian/vol-283/year-0942/part-04/sources/library/tongjian-283-942-autumn-winter/source.txt", "note": "《资治通鉴》卷283·天福七年八月至年末，段落 zizhi-tongjian-a63549944a71-p003363；已核上下文及传主，纸本及异文待核。", "id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"title": "新五代史·卷9·晋本纪·天福七年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/03f32f35d226d0f16dc68b58596ef35b6835b720/content/books/zizhi-tongjian/vol-283/year-0942/part-03/sources/library/xinwudaishi-009-942-succession/source.txt", "note": "《新五代史》卷9·晋本纪·天福七年，段落 xin-wudaishi-b08f244b9241-p000333；已核上下文及传主，纸本及异文待核。", "id": "ce49f762-1a4b-5f35-8f95-f69e69f10973"}, {"title": "新五代史·卷65·南汉世家·钱帛馆之战", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d0f7599ab625e6aecad46626068a963056a59c78/content/books/zizhi-tongjian/vol-283/year-0942/part-04/sources/library/xinwudaishi-065-zhang-yuxian-battle/source.txt", "note": "《新五代史》卷65·南汉世家·钱帛馆之战，段落 xin-wudaishi-b08f244b9241-p003279；已核上下文及传主，纸本及异文待核。", "id": "8f5916ed-cd8d-54c4-9694-a8863b6edb56"}, {"title": "新五代史·卷68·闽世家·王延羲妻李氏", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7e9f7a7ea4b22cbbe6d05277dd5c16ed51a9e06/content/books/zizhi-tongjian/vol-283/year-0942/part-01/sources/library/xinwudaishi-068-min-li-empress/source.txt", "note": "《新五代史》卷68·闽世家·王延羲妻李氏，段落 xin-wudaishi-b08f244b9241-p003411；已核上下文及传主，纸本及异文待核。", "id": "f65572e7-91e0-5d18-a84c-68aa6429f9d4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张遇贤", "aliases": ["張遇賢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "博罗县吏。942年循州起事者拥立他为领袖，他称中天八国王、改元永乐并置官。南汉派刘弘昌、刘弘杲征讨，二人在钱帛馆被围，后由将领救出。生卒年未载。", "biography": null, "status": "draft", "id": "508b1255-a234-507d-a64f-ede078d1c559"}, {"name": "刘传", "aliases": ["劉傳"], "era": "五代十国", "birth_year": null, "death_year": 942, "description": "南汉循州刺史。942年十月丙子，张遇贤攻陷循州，刘传被杀。出生年未载。", "biography": null, "status": "draft", "id": "46ea5d99-5bd5-51f8-8002-fd35e265033e"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "董遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋三司使。942年十一月本纪记他从金吾卫大将军、权判三司任三司使；通鉴记他加重盐商征税以求财利，官营卖盐随后恢复。生卒年未载。", "biography": null, "status": "draft", "id": "9a9cc2e3-bc2b-597f-955b-fdc92cdbba91"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "李仁遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国盐铁使、右仆射，史称李敏之子、王延羲之甥。942年十二月任左仆射兼中书侍郎、同平章事。父亲李敏与已录同名人物是否同人尚待核对，未直接连接父亲关系。生卒年未载。", "biography": null, "status": "draft", "id": "0ebdfee8-6c02-58dd-8d08-8f9a2a4edffc"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "李光准", "aliases": ["李光準"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国翰林学士、吏部侍郎。942年十二月任中书侍郎兼户部尚书、同平章事。史书回顾他在酒宴中醉酒触怒王延羲，被下令处死，但官吏未执行，次日又恢复职位。生卒年未载。", "biography": null, "status": "draft", "id": "3147c4c7-55fe-53ad-8887-8354e082b567"}, {"name": "周维岳", "aliases": ["周維岳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国翰林学士。史书记他在王延羲宴饮中被关入狱中，王延羲酒醒后将他释放；另一次宴中险被剖腹，因有人劝阻而免于被杀。具体年月及生卒年未载。", "biography": null, "status": "draft", "id": "cb6d12a6-c290-56b7-8b40-1a0488602ad8"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
