ft", "id": "27944285-f24a-5f83-a23e-40e5f8111fb2", "subject_id": "7c287f4a-3d06-58ad-aea2-1d6b4f8d03b0", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "description", "claim_text": "石敬瑭接受放开盐禁、改征食盐钱的建议。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p037·原文件第42行", "note": "原文：高祖从之。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "3836f87d-8616-55b0-9d8b-55b19fbe01c3", "subject_id": "13f6a78d-668e-51e8-ba2f-c26c720149a2", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "石敬瑭在位期间，具体年月未载", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p037·原文件第42行", "note": "原文：高祖从之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "a7ccddfa-6d36-52af-be97-e85ee51142b6", "subject_id": "13f6a78d-668e-51e8-ba2f-c26c720149a2", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "石敬瑭：接受建议允许民间贩盐并改征食盐钱。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p037·原文件第42行", "note": "原文：高祖从之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "320040b5-9769-5bad-8416-79992b1cff3a", "subject_id": "fae55185-d4b0-5463-b02b-271beb38eab6", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》补记放开盐禁后，令州郡按五等户征食盐钱，上户千文、下户二百。", "citation": "《旧五代史》卷81·晋少帝本纪·天福七年十一月，段落 jiu-wudaishi-205deb4a7860-p001983；已核上下文及传主，纸本及异文待核。", "note": "原文：遂開鹽禁，許通商，令州郡配征人戶食鹽錢，上戶千文，下戶二百，分為五等，；核对说明：这是过去政策及分户额，不当董遇十一月的新盐商关税。", "status": "draft", "id": "0b92cc9f-515f-504a-a5f9-3aa4f7a7cb33", "subject_id": "13f6a78d-668e-51e8-ba2f-c26c720149a2", "source_id": "339cc68d-7f97-514c-99fa-e779b48fe477"}, {"subject_table": "event", "field_path": "description", "claim_text": "放开盐禁后盐价下降，每斤降至十钱。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p037·原文件第42行", "note": "原文：俄而盐价顿贱，每斤至十钱。；核对说明：俄而不换算固定天数；价格为史书概