ect_id": "1b82fd43-ef3d-5d5f-97da-2566c9b87924", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王延羲：酒醒后释放周维岳。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：吏拂榻待之，曰：“相公昨夜宿此，尚书勿忧。”醒而释之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "ef83700f-ae7e-50fe-b972-8902a69e6f02", "subject_id": "036fa666-2d45-55df-b5bd-f3c495e5960d", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "description", "claim_text": "另一次宴饮，王延羲因酒有别肠的说法，命拖周维岳下殿，想剖看酒肠。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：他日，又宴，侍臣皆以醉去，独维岳在。曦曰：“维岳身甚小，何饮酒之多？”左右或曰：“酒有别肠，不必长大。”曦欣然，命捽维岳下殿，欲剖视其酒肠。；核对说明：酒有别肠为左右说法，不当现代解剖事实；欲剖未执行，不造已剖腹事件。", "status": "draft", "id": "88b27d69-2bfa-52f8-a400-b07127ba7c1a", "subject_id": "7789013f-694c-50d1-a4c8-e91e55b805f3", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "王延羲在位期间另一场宴饮，具体年月未载", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：他日，又宴，侍臣皆以醉去，独维岳在。曦曰：“维岳身甚小，何饮酒之多？”左右或曰：“酒有别肠，不必长大。”曦欣然，命捽维岳下殿，欲剖视其酒肠。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "f5265600-4c80-5558-befb-37230faf1f1b", "subject_id": "7789013f-694c-50d1-a4c8-e91e55b805f3", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王延羲：听信酒有别肠说法，命拖人下殿并计划剖看。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：他日，又宴，侍臣皆以醉去，独维岳在。曦曰：“维岳身甚小，何饮酒之多？”左右或曰：“酒有别肠，不必长大。”曦欣然，命捽维岳下殿，欲剖视其酒肠。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "0485f539-20fe-5592-a7c9-c072ab0f50f2", "subject_id": "9039286f-e022-5b29-b4a4-f8b11f47dcd8", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周维岳：因饮酒量被君主计划剖看肠胃。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：他日，又宴，侍臣皆以醉去，独维岳在。曦曰：“维岳身甚小，何饮酒之多？”左右或曰：“酒有别肠，不必长大。”曦欣然，命捽维岳下殿，欲剖视其酒肠。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "84261dda-466e-500d-adcb-574628aef39c", "subject_id": "11a0729e-85cb-5a8a-a5de-d67dc8adf855", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "description", "claim_text": "有人劝王延羲留下能陪他饮酒的周维岳，周维岳免于被杀。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：或曰：“杀维岳，无人复能侍陛下剧饮者。”乃舍之。；核对说明：劝者未具名，不补与周维岳的亲属或结党关系。", "status": "draft", "id": "08add7b7-b2e9-5045-a499-01b804204c85", "subject_id": "72879612-b9b9-5fc9-aaf0-0180aa4766db", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "上述拟剖酒肠事件中，具体年月未载", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：或曰：“杀维岳，无人复能侍陛下剧饮者。”乃舍之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "107927b0-4071-50f4-8cad-07f9994de475", "subject_id": "72879612-b9b9-5fc9-aaf0-0180aa4766db", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王延羲：听从劝阻而放过周维岳。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：或曰：“杀维岳，无人复能侍陛下剧饮者。”乃舍之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "0cc269e2-6206-5880-a3db-e24f27502630", "subject_id": "cdc40b0a-d52f-5c2f-be8f-be1d886e3932", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周维岳：因有人劝阻而免于被杀。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p038·原文件第43行", "note": "原文：或曰：“杀维岳，无人复能侍陛下剧饮者。”乃舍之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "247ae69b-e850-5312-ae77-0871009dfc53", "subject_id": "2f5d6efe-9c80-5366-9448-43e28fd3e8ee", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "description", "claim_text": "石重贵初即位时，景延广提议向契丹称孙，不称臣。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p039·原文件第44行", "note": "原文：帝之初即位也，大臣议奉表称臣告哀于契丹，景延广请致书称孙而不称臣。；核对说明：政治称孙不新建生物血缘祖孙关系；不是十二月新即位或首次才商议。", "status": "draft", "id": "7586bf2e-2403-52ae-a81e-920da2e47595", "subject_id": "ed4d088e-c5d8-5bb3-8427-cc563f305574", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "942年六月石重贵初即位时，具体讨论日未载", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p039·原文件第44行", "note": "原文：帝之初即位也，大臣议奉表称臣告哀于契丹，景延广请致书称孙而不称臣。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "a76195ab-547b-5bb2-b7c3-708645d7895b", "subject_id": "ed4d088e-c5d8-5bb3-8427-cc563f305574", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person", "field_path": "description", "claim_text": "景延广：反对奉表称臣，提议致书称孙。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p039·原文件第44行", "note": "原文：帝之初即位也，大臣议奉表称臣告哀于契丹，景延广请致书称孙而不称臣。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "1e03c8f6-b71a-5551-86fb-1a677eb6368a", "subject_id": "de8a964e-a028-50ee-8d54-2cbfda481e98", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "景延广：反对奉表称臣，提议致书称孙。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p039·原文件第44行", "note": "原文：帝之初即位也，大臣议奉表称臣告哀于契丹，景延广请致书称孙而不称臣。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "7698a2a9-1fe5-5e22-8bd1-04b3201093a0", "subject_id": "e402970a-5df4-53ce-b681-fd6dae463165", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "石重贵：在初即位时听取交涉称谓建议。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p039·原文件第44行", "note": "原文：帝之初即位也，大臣议奉表称臣告哀于契丹，景延广请致书称孙而不称臣。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "fc5ee1c3-975b-56de-98b5-f7039cea364f", "subject_id": "e8c8d800-2df8-5a0d-870f-b5c89c51c9e1", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》也记出帝初立，景延广拒绝奉表称臣，只主张致书称孙。", "citation": "《新五代史》卷29·景延广传·晋与契丹交涉，段落 xin-wudaishi-b08f244b9241-p001067；已核上下文及传主，纸本及异文待核。", "note": "原文：初，出帝立，晉大臣議告契丹，致表稱臣，延廣獨不肯，但致書稱孫而已，；核对说明：同一初立交涉讨论，其他后续言论发生日期未载，不强定全在六月即位当天。", "status": "draft", "id": "8cfe34b3-7123-5857-91bf-58f6452d3b54", "subject_id": "ed4d088e-c5d8-5bb3-8427-cc563f305574", "source_id": "82078cac-bb42-5526-b3f6-656e97070284"}, {"subject_table": "event", "field_path": "description", "claim_text": "李崧劝石重贵为保国家向契丹称臣，警告拒绝称臣将来可能引发战争。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p039·原文件第44行", "note": "原文：李崧曰：“屈身以为社稷，何耻之有！陛下如此，他日必躬擐甲胄，与契丹战，于时悔无益矣。”；核对说明：他日必战是李崧的警告，不当作此时已经发生的战争。", "status": "draft", "id": "eb0300e3-7e9a-581a-ae54-f8211a96c7c8", "subject_id": "78db2838-7d7b-5a62-bd8d-b43c6164d0eb", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "942年石重贵初即位时，具体讨论日未载", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p039·原文件第44行", "note": "原文：李崧曰：“屈身以为社稷，何耻之有！陛下如此，他日必躬擐甲胄，与契丹战，于时悔无益矣。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "1a1d721e-42e8-585d-9f4c-34ba0017ba70", "subject_id": "78db2838-7d7b-5a62-bd8d-b43c6164d0eb", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person", "field_path": "description", "claim_text": "李崧：劝称臣并警告将来可能开战。", "citation": "卷283·后晋天福七年（942；十月至十二月条下及追述）·zztj-v283-y0942-p039·原文件第44行", "note": "原文：李崧曰：“屈身以为社稷，何耻之有！陛下如此，他日必躬擐甲胄，与契丹战，于时悔无益矣。”；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "0e708e92-760d-5694-b328-3019e2bb2b64", "subject_id": "42727c37-29c7-534f-b0f7-900992c16def", "source_id": "e20ca533-e3ab-5002-a918-c3a81dffba82"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李崧：劝称臣并警告将来可能开战。", "citation": "卷283·后晋天福